<?php
if(!isset($pdo,$uid,$in,$action)){http_response_code(404);exit;}
if($action==='resource_save'){$kind=$in['kind']??'';if(!in_array($kind,['stock_batches','business_capacity']))out(['error'=>'Неизвестный ресурс'],422);$d=cleanOpportunityResource($kind,$in['data']??[]);$id=(int)($in['id']??0);if($id){$q=$pdo->prepare('UPDATE aulieata_records SET payload=? WHERE id=? AND user_id=? AND kind=? AND archived=0');$q->execute([json_encode($d,JSON_UNESCAPED_UNICODE),$id,$uid,$kind]);if(!$q->rowCount())out(['error'=>'Запись не найдена или не изменена'],409);}else $id=platformRecord($pdo,$uid,$kind,$d);out(['ok'=>true,'id'=>$id]);}
if($action==='promotion_generate'){
$margin=filter_var($in['margin']??20,FILTER_VALIDATE_FLOAT);if($margin===false||$margin<0||$margin>90)out(['error'=>'Минимальная маржа от 0 до 90%'],422);$ids=buildPromotionDrafts($pdo,$uid,$margin,$businessProfile,$runtimeConfig);out(['ok'=>true,'ids'=>$ids]);
}
if($action==='promotion_publish'){$id=(int)($in['id']??0);$q=$pdo->prepare("SELECT payload FROM aulieata_records WHERE id=? AND user_id=? AND kind='promotion_drafts' AND archived=0");$q->execute([$id,$uid]);$d=json_decode($q->fetchColumn()?:'{}',true);$eligible=[];foreach(scanBusinessSignals($pdo,$uid) as $s)if($s['eligible'])$eligible[$s['record_id']]=$s;$source=$eligible[$d['source_id']??0]??null;if(!$d||!$source||$d['valid_until']<localBusinessDay()||$source['quantity']<=0||$source['cost']<=0||$d['offer_price']<ceil($source['cost']/(1-$d['min_margin']/100)*100)/100)out(['error'=>'Ресурс или допустимая цена изменились. Пересоздайте акцию.'],409);if($businessProfile['type']==='medical')out(['error'=>'Публикация товарных акций для медицинского профиля отключена'],422);$d['status']='published';$d['cost']=$source['cost'];$d['gross_margin_percent']=round((1-$source['cost']/$d['offer_price'])*100,1);if(!empty($source['expires_on']))$d['valid_until']=min($d['valid_until'],$source['expires_on']);$d['quantity_limit']=min($d['quantity_limit'],$source['quantity']);$q=$pdo->prepare('UPDATE aulieata_records SET payload=? WHERE id=? AND user_id=?');$q->execute([json_encode($d,JSON_UNESCAPED_UNICODE),$id,$uid]);out(['ok'=>true]);}
if($action==='promotion_task'){$q=$pdo->prepare("SELECT payload FROM aulieata_records WHERE id=? AND user_id=? AND kind='promotion_drafts' AND archived=0");$q->execute([(int)($in['id']??0),$uid]);$d=json_decode($q->fetchColumn()?:'{}',true);if(!$d)out(['error'=>'Акция не найдена'],404);$id=platformRecord($pdo,$uid,'tasks',['name'=>'Подготовить акцию: '.$d['name'],'text'=>$d['mechanic']."\n".implode("\n",$d['steps'])."\nДо публикации проверить сроки, остаток и цену.",'status'=>'Новая']);out(['ok'=>true,'id'=>$id]);}
